command:
$ErrorActionPreference = "Stop"
git fetch origin main work/high-contrast-acceptance --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "92c16faf6c56c89cf4bff5230482db3ac312a82f") { throw "main moved" }
if ((git rev-parse origin/work/high-contrast-acceptance).Trim() -ne "179155986fdcfeb0dacf213b3cd892b78b0b3363") { throw "work branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/high-contrast-acceptance origin/work/high-contrast-acceptance
if ($LASTEXITCODE -ne 0) { throw "checkout work branch failed" }
git merge --no-edit origin/main
if ($LASTEXITCODE -ne 0) { git merge --abort 2>$null; throw "main merge conflicted" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed after main merge" }
$head=(git rev-parse HEAD).Trim()
Write-Host ("INTEGRATED_HEAD=" + $head)
git push origin HEAD:refs/heads/work/high-contrast-acceptance
if ($LASTEXITCODE -ne 0) { throw "push integrated work branch failed" }
Write-Host "HIGH_CONTRAST_POLICY_SYNC_PASS"
